	// blocking scales; can be wired into more advanced tiling if desired).
	static constexpr std::size_t block_i = 32;
	static constexpr std::size_t block_j = 32;
	static constexpr std::size_t block_k = 32;
	static constexpr std::size_t block_l = 32;
	static constexpr std::size_t block_m = 32;
} tuning;

// Array initialization
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	const auto ni = A | get_length<'i'>();
	const auto nk = A | get_length<'k'>();
	const auto nj = B | get_length<'j'>();
	const auto nm = C | get_length<'m'>();
	const auto nl = D | get_length<'l'>();

	// All traversals below iterate with the inner (contiguous) dimension
	// innermost, so writes are cache‑ and bandwidth‑friendly.

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	traverser(A).template for_dims<'i', 'k'>([=](auto trav) {
		auto state = trav.state();
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % ni) / (5 * ni);
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).template for_dims<'k', 'j'>([=](auto trav) {
		auto state = trav.state();
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)((k * (j + 1) + 2) % nj) / (5 * nj);
	});

