// computation kernel
//
// The original version computed each output element independently and
// accumulated over the reduction dimension in the innermost loop:
//
//   E[i][j] = sum_k A[i][k] * B[k][j]
//
// which gives good locality for A and the scalar E[i][j], but poor
// locality for B (accessed with a large stride along k).
//
// Here we explicitly choose loop orders that keep all matrices accessed
// with their contiguous dimension in the innermost loop:
//
//   E: i‑k‑j   (j innermost, contiguous in E and B)
//   F: j‑m‑l   (l innermost, contiguous in F and D)
//   G: i‑j‑l   (l innermost, contiguous in G and F)
//
// We also separate the initialization (zeroing) of E, F, G from the
// accumulation loops. This adds only O(N²) work while allowing the
// main O(N³) kernels to use pure "+=" updates, which simplifies the
// generated code and usually improves vectorization.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

	// Local aliases for potential further tuning (e.g. tiling), currently
	// just documenting the intended blocking scales.
	static constexpr std::size_t block_i [[maybe_unused]] = tuning.block_i;
	static constexpr std::size_t block_j [[maybe_unused]] = tuning.block_j;
	static constexpr std::size_t block_k [[maybe_unused]] = tuning.block_k;
	static constexpr std::size_t block_l [[maybe_unused]] = tuning.block_l;
	static constexpr std::size_t block_m [[maybe_unused]] = tuning.block_m;

	#pragma scop

	// ---------------------------------------------------------------------
	// 0. Initialize outputs to zero
	// ---------------------------------------------------------------------
	traverser(E).for_each([&](auto s) {
		E[s] = (num_t)0.0;
	});
	traverser(F).for_each([&](auto s) {
		F[s] = (num_t)0.0;
	});
	traverser(G).for_each([&](auto s) {
		G[s] = (num_t)0.0;
	});

	// ---------------------------------------------------------------------
	// 1. E := A * B
	//
	//    E is (i x j)
	//    A is (i x k)  row‑major    (inner: k)
	//    B is (k x j)  row‑major    (inner: j)
	//
	// Loop order: i, k, j
	//
	//  for i
	//    for k
	//      a = A[i,k]
	//      for j
	//        E[i,j] += a * B[k,j];
	//
	// A[i,k] is reused across the full j‑row,
	// B[k,j] and E[i,j] are walked contiguously along j.
	// ---------------------------------------------------------------------
	traverser(E, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// trav_ik has i, k fixed; j is still free.
		const num_t a_ik = A[trav_ik]; // reuse across all j for this (i,k)

		trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
			// trav_ikj has i, k, j fixed.
			E[trav_ikj] += a_ik * B[trav_ikj];
		});
	});

	// ---------------------------------------------------------------------
	// 2. F := C * D
	//
	//    F is (j x l)
	//    C is (j x m)  row‑major    (inner: m)
	//    D is (m x l)  row‑major    (inner: l)
	//
	// Loop order: j, m, l
	//
	//  for j
	//    for m
	//      c = C[j,m]
	//      for l
	//        F[j,l] += c * D[m,l];
	//
	// C[j,m] is reused across the full l‑row,
	// D[m,l] and F[j,l] are walked contiguously along l.
	// ---------------------------------------------------------------------
	traverser(F, C, D).template for_dims<'j', 'm'>([&](auto trav_jm) {
		// trav_jm has j, m fixed; l is still free.
		const num_t c_jm = C[trav_jm]; // reuse across all l for this (j,m)

		trav_jm.template for_dims<'l'>([&](auto trav_jml) {
			// trav_jml has j, m, l fixed.
			F[trav_jml] += c_jm * D[trav_jml];
		});
	});

	// ---------------------------------------------------------------------
	// 3. G := E * F
	//
	//    G is (i x l)
	//    E is (i x j)  row‑major    (inner: j)
	//    F is (j x l)  row‑major    (inner: l)
	//
	// Loop order: i, j, l
	//
	//  for i
	//    for j
	//      e = E[i,j]
	//      for l
	//        G[i,l] += e * F[j,l];
	//
	// E[i,j] is reused across the full l‑row,
	// F[j,l] and G[i,l] are walked contiguously along l.
	// ---------------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// trav_ij has i, j fixed; l is still free.
		const num_t e_ij = E[trav_ij]; // reuse across all l for this (i,j)

		trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
			// trav_ijl has i, j, l fixed.
			G[trav_ijl] += e_ij * F[trav_ijl];
		});
	});

	#pragma endscop
}

} // namespace

