	DEFINE_PROTO_STRUCT(d_layout, l_vec ^ m_vec);

	// E: i x j, inner dimension j (E[i,j] row-major in j)
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);

	// F: j x l, inner dimension l (F[j,l] laid out contiguously in l)
	DEFINE_PROTO_STRUCT(f_layout, l_vec ^ j_vec);

	// G: i x l, inner dimension l (G[i,l] laid out contiguously in l)
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);

