	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// Zero-initialize E, F, G once before accumulation
	// ---------------------------------------------------------------------
	traverser(E).for_each([&](auto s) {
		E[s] = (num_t)0.0;
	});
	traverser(F).for_each([&](auto s) {
		F[s] = (num_t)0.0;
	});
	traverser(G).for_each([&](auto s) {
		G[s] = (num_t)0.0;
	});

	// ---------------------------------------------------------------------
	// E := A * B
	//
	// Original mathematical form:
	//   E[i,j] = sum_k A[i,k] * B[k,j]
	//
	// Optimized loop nest:
	//   for i
	//     for k
	//       aik = A[i,k]
	//       for j
	//         E[i,j] += aik * B[k,j]
	//
	// With our layouts:
	//   - A: inner dimension k, we load a single A[i,k] once per (i,k)
	//   - B: inner dimension j, inner loop over j is contiguous in memory
	//   - E: inner dimension j, inner loop over j updates a contiguous row
	// ---------------------------------------------------------------------
	traverser(E, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// A[i,k] is invariant across the inner j-loop; load once
		const num_t aik = A[trav_ik];

		// now traverse all j for fixed (i,k)
		trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
			E[trav_ikj] += aik * B[trav_ikj];
		});
	});

	// ---------------------------------------------------------------------
	// F := C * D
	//
	// Mathematical form:
	//   F[j,l] = sum_m C[j,m] * D[m,l]
	//
	// Optimized loop nest:
	//   for j
	//     for m
	//       cjm = C[j,m]
	//       for l
	//         F[j,l] += cjm * D[m,l]
	//
	// Layout rationale:
	//   - C: inner dimension m, outer j
	//       -> for fixed j, varying m is contiguous.
	//   - D: inner dimension l, outer m
	//       -> for fixed m, varying l is contiguous.
	//   - F: inner dimension l, outer j
	//       -> for fixed j, varying l is contiguous.
	// ---------------------------------------------------------------------
	traverser(F, C, D).template for_dims<'j', 'm'>([&](auto trav_jm) {
		const num_t cjm = C[trav_jm];

		trav_jm.template for_dims<'l'>([&](auto trav_jml) {
			F[trav_jml] += cjm * D[trav_jml];
		});
	});

	// ---------------------------------------------------------------------
	// G := E * F
	//
	// Mathematical form:
	//   G[i,l] = sum_j E[i,j] * F[j,l]
	//
	// Optimized loop nest:
	//   for i
	//     for j
	//       eij = E[i,j]
	//       for l
	//         G[i,l] += eij * F[j,l]
	//
	// Layout rationale:
	//   - E: inner dimension j, outer i
	//       -> E[i,j] accessed once per (i,j).
	//   - F: inner dimension l, outer j
	//       -> for fixed j, varying l is contiguous.
	//   - G: inner dimension l, outer i
	//       -> for fixed i, varying l is contiguous.
	// ---------------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		const num_t eij = E[trav_ij];

		trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
			G[trav_ijl] += eij * F[trav_ijl];
		});
	});

	#pragma endscop
}

