// computation kernel
//
// Optimized 3MM:
//   E = A * B
//   F = C * D
//   G = E * F
//
// For each multiplication we:
//   1) Explicitly zero the result matrix.
//   2) Use a blocked, cache-friendly traversal on the reduction dimension
//      (k for E, m for F, j for G) using noarr::into_blocks_dynamic.
//   3) For each (i, block, in-block index) we load the left operand once and
//      iterate the right operand along its contiguous dimension, improving
//      memory locality for A/C/E and B/D/F.
// The use of into_blocks_dynamic ensures correctness even when the problem
// sizes are not divisible by the block sizes: the extra "presence" dimensions
// ('r', 's', 't') automatically skip out-of-range elements.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

	// Blocked views for the three reduction dimensions.
	// - For E = A * B we block over 'k' into ('K', 'k') with presence 'r'.
	// - For F = C * D we block over 'm' into ('M', 'm') with presence 's'.
	// - For G = E * F we block over 'j' into ('J', 'j') with presence 't'.
	//
	// Presence dimensions ('r', 's', 't') have length 0 or 1 and are
	// responsible for cutting off the "overhanging" part of the last block
	// when the dimension is not an exact multiple of the block size.
	const auto k_blocks =
		noarr::into_blocks_dynamic<'k', 'K', 'k', 'r'>(noarr::lit<BLOCK_K>);
	const auto m_blocks =
		noarr::into_blocks_dynamic<'m', 'M', 'm', 's'>(noarr::lit<BLOCK_M>);
	const auto j_blocks =
		noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(noarr::lit<BLOCK_J>);

	#pragma scop

	// ---------------------------------------------------------------------
	// 1. Zero-out result matrices E, F, G.
	// ---------------------------------------------------------------------

	traverser(E).for_each([&](auto state) {
		E[state] = (num_t)0.0;
	});

	traverser(F).for_each([&](auto state) {
		F[state] = (num_t)0.0;
	});

	traverser(G).for_each([&](auto state) {
		G[state] = (num_t)0.0;
	});

	// ---------------------------------------------------------------------
	// 2. E := A * B
	//
	//    E(i, j) = sum_k A(i, k) * B(k, j)
	//
	// Blocked loop order:
	//    i (row of E / A)
	//    K (block of k)
	//    r (presence of this (K, k) pair)
	//    k (within-block k)
	//    j (column of E / B) -- innermost, contiguous in B and E
	//
	// Within each (i, K, r, k) we:
	//   - load a_val = A(i, k) once
	//   - iterate j to traverse a full contiguous row of B(k, :)
	//     and update the contiguous row of E(i, :)
	// ---------------------------------------------------------------------
	traverser(E, A, B)
		.order(k_blocks)
		.template for_dims<'i', 'K', 'r', 'k'>([&](auto trav_iKrk) {
			// Load A(i, k) once per inner j-loop; A ignores 'K' and 'r'.
			num_t a_val = A[trav_iKrk];

			// Now walk j as the innermost loop. This makes B(k, j) and
			// E(i, j) contiguous accesses in memory.
			trav_iKrk.template for_dims<'j'>([&](auto trav_iKrkj) {
				E[trav_iKrkj] += a_val * B[trav_iKrkj];
			});
		});

	// ---------------------------------------------------------------------
	// 3. F := C * D
	//
	//    F(j, l) = sum_m C(j, m) * D(m, l)
	//
	// Blocked loop order (analogous to E):
	//    j (row of F / C)
	//    M (block of m)
	//    s (presence)
	//    m (within-block m)
	//    l (column of F / D) -- innermost, contiguous in D and F
	//
	// For each (j, M, s, m):
	//   - load c_val = C(j, m) once
	//   - iterate l over a contiguous row of D(m, :) and update F(j, :)
	// ---------------------------------------------------------------------
	traverser(F, C, D)
		.order(m_blocks)
		.template for_dims<'j', 'M', 's', 'm'>([&](auto trav_jMsm) {
			// Load C(j, m) once per inner l-loop; C ignores 'M' and 's'.
			num_t c_val = C[trav_jMsm];

			// Walk l as the innermost loop, giving contiguous accesses
			// to both D(m, l) and F(j, l).
			trav_jMsm.template for_dims<'l'>([&](auto trav_jMsml) {
				F[trav_jMsml] += c_val * D[trav_jMsml];
			});
		});

	// ---------------------------------------------------------------------
	// 4. G := E * F
	//
	//    G(i, l) = sum_j E(i, j) * F(j, l)
	//
	// Blocked over 'j' (the reduction dimension here):
	//    i (row of G / E)
	//    J (block of j)
	//    t (presence)
	//    j (within-block j)
	//    l (column of G / F) -- innermost, contiguous in F and G
	//
	// For each (i, J, t, j):
	//   - load e_val = E(i, j) once
	//   - iterate l over contiguous F(j, :) and update G(i, :)
	// ---------------------------------------------------------------------
	traverser(G, E, F)
		.order(j_blocks)
		.template for_dims<'i', 'J', 't', 'j'>([&](auto trav_iJtj) {
			// Load E(i, j) once per inner l-loop; E ignores 'J' and 't'.
			num_t e_val = E[trav_iJtj];

			// Walk l as the innermost loop, accessing F(j, l) and G(i, l)
			// contiguously.
			trav_iJtj.template for_dims<'l'>([&](auto trav_iJtjl) {
				G[trav_iJtjl] += e_val * F[trav_iJtjl];
			});
		});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

