		auto state = trav.state();
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = (num_t)((j * (m + 3) % nl)) / (5 * nl);
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).template for_dims<'m', 'l'>([=](auto trav) {
		auto state = trav.state();
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = (num_t)(((m * (l + 2) + 2) % nk)) / (5 * nk);
	});
}

// computation kernel
//
// This version is optimized for better data locality and cache efficiency:
//
// 1) Each matrix multiplication is written with a loop order that maximizes
//    reuse of the left operand and ensures that the innermost loop walks
//    the contiguous dimension of the right operand and the result.
//
// 2) For the 'j' and 'l' dimensions we additionally apply cache blocking
//    using noarr::into_blocks_static + noarr::hoist via traverser::order().
//    This preserves the original layout but changes traversal order to
//    operate on small tiles that fit better into caches. into_blocks_static
//    automatically and correctly handles edge tiles when the dimension size
//    is not a multiple of the tile size.
//
// All traversal is done with noarr::traverser and for_dims / for_each.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	// Proto-structures describing how we want to block and traverse the
	// 'j' and 'l' dimensions. The layout is preserved; only the index
	// space is split into (border-flag, block-index, in-block-index).
	//  - 'y' and 'u' are "border" tuple-like dimensions that distinguish
	//    full tiles from border tiles.
	//  - 'J' and 'L' are block indices.
	//  - 'j' and 'l' remain the intra-block indices with the original
	//    semantics, so all existing code can keep using just 'j'/'l'.
	//
	// hoist<'J'> / hoist<'L'> makes the block index the outer dimension
	// for the blocked traversals.
	const auto j_block_traversal =
		into_blocks_static<'j', 'y', 'J', 'j'>(kernel_tuning::j_block)
		^ hoist<'J'>();

	const auto l_block_traversal =
		into_blocks_static<'l', 'u', 'L', 'l'>(kernel_tuning::l_block)
		^ hoist<'L'>();

	#pragma scop
	// ------------------------------------------------------------------
	// E := A * B
	// We use loop order i-k-j:
	//   for i
	//     for k
	//       a_ik = A[i,k]
	//       for j (blocked)
	//         E[i,j] += a_ik * B[k,j]
	//
	// This reuses A[i,k] across all j (kept in a register) and walks B
	// and E contiguously in 'j'. The j-loop is additionally blocked.
	// ------------------------------------------------------------------

	// Initialize E to zero
	traverser(E).for_each([&](auto s) {
		E[s] = (num_t)0.0;
	});

	traverser(E, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// trav_ik has 'i' and 'k' fixed, 'j' is still free.
		const num_t a_val = A[trav_ik];

		// Block the 'j' dimension while preserving layout.
		// The state passed to the lambda still only exposes 'i','k','j'
		// (no explicit 'J' or 'y'), but 'j' is now traversed in tiles.
		auto trav_ik_jblocked = trav_ik.order(j_block_traversal);
		trav_ik_jblocked.for_each([&](auto state) {
			E[state] += a_val * B[state];
		});
	});


	// ------------------------------------------------------------------
	// F := C * D
	// We use loop order j-m-l:
	//   for j
	//     for m
	//       c_jm = C[j,m]
	//       for l (blocked)
	//         F[j,l] += c_jm * D[m,l]
	//
	// This reuses C[j,m] across all l and walks D and F contiguously
	// in 'l'. The l-loop is additionally blocked.
	// ------------------------------------------------------------------

	// Initialize F to zero
	traverser(F).for_each([&](auto s) {
		F[s] = (num_t)0.0;
	});

	traverser(F, C, D).template for_dims<'j', 'm'>([&](auto trav_jm) {
		// trav_jm has 'j' and 'm' fixed, 'l' is still free.
		const num_t c_val = C[trav_jm];

		// Block the 'l' dimension for better cache locality.
		auto trav_jm_lblocked = trav_jm.order(l_block_traversal);
		trav_jm_lblocked.for_each([&](auto state) {
			F[state] += c_val * D[state];
		});
	});


	// ------------------------------------------------------------------
	// G := E * F
	// We use loop order i-j-l:
	//   for i
	//     for j
	//       e_ij = E[i,j]
	//       for l (blocked)
	//         G[i,l] += e_ij * F[j,l]
	//
	// This reuses E[i,j] across all l and walks F and G contiguously
	// in 'l'. Again, the l-loop is blocked.
	// ------------------------------------------------------------------

	// Initialize G to zero
	traverser(G).for_each([&](auto s) {
		G[s] = (num_t)0.0;
	});

	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// trav_ij has 'i' and 'j' fixed, 'l' is still free.
		const num_t e_val = E[trav_ij];

		// Block the 'l' dimension.
		auto trav_ij_lblocked = trav_ij.order(l_block_traversal);
		trav_ij_lblocked.for_each([&](auto state) {
			G[state] += e_val * F[state];
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_3mm(E.get_ref(), A.get_ref(), B.get_ref(),
	           F.get_ref(), C.get_ref(), D.get_ref(), G.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
